	var val3 float64
	var greatest float64
	var tempCY float64
	var tempLT float64
	var tempHT float64
	var medianPrice float64
	var band float64
	var basicUpper float64
	var basicLower float64
	var closeToday float64
	var cur_outSupertrend float64
	var cur_outTrend int32
